package br.com.sussmartcare.patientjourney.adapters.in.rest; import br.com.sussmartcare.patientjourney.application.*; import br.com.sussmartcare.patientjourney.domain.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1") public class VisitController { private final VisitApplicationService app; public VisitController(VisitApplicationService a){app=a;} public record CreateVisitRequest(@NotNull UUID patientId,@NotNull UUID facilityId,@NotNull Channel channel){} public record AnamnesisRequest(@NotBlank String text){} @PostMapping("/pre-visits") public ResponseEntity<Visit> create(@Valid @RequestBody CreateVisitRequest r){return ResponseEntity.status(201).body(app.create(r.patientId(),r.facilityId(),r.channel()));} @GetMapping("/visits/{id}") public Visit get(@PathVariable UUID id){return app.get(id);} @PutMapping("/pre-visits/{id}/anamnesis") public Visit anamnesis(@PathVariable UUID id,@Valid @RequestBody AnamnesisRequest r){return app.anamnesis(id,r.text());} @PostMapping("/pre-visits/{id}/check-in") public Visit checkIn(@PathVariable UUID id){return app.checkIn(id);} }